// Automated smoke test for the lobby server: two clients create/join a lobby,
// start a DM match, exchange state/shoot/hit, score a kill, and finish at 10.
import WebSocket from 'ws';

const URL = 'ws://localhost:3000';
let failed = 0;
const ok = (cond, label) => {
  console.log(`${cond ? 'PASS' : 'FAIL'}  ${label}`);
  if (!cond) failed++;
};

function client(name) {
  const ws = new WebSocket(URL);
  const c = { ws, name, id: null, inbox: [] };
  ws.on('message', d => {
    const m = JSON.parse(d);
    if (m.t === 'welcome') c.id = m.id;
    c.inbox.push(m);
  });
  c.send = o => ws.send(JSON.stringify(o));
  c.wait = (type, timeout = 3000) => new Promise((res, rej) => {
    const t0 = Date.now();
    const iv = setInterval(() => {
      const i = c.inbox.findIndex(m => m.t === type);
      if (i >= 0) { clearInterval(iv); res(c.inbox.splice(i, 1)[0]); }
      else if (Date.now() - t0 > timeout) { clearInterval(iv); rej(new Error(`${name}: timeout waiting for "${type}"`)); }
    }, 10);
  });
  c.open = new Promise(res => ws.on('open', res));
  return c;
}

const a = client('A');
const b = client('B');
await Promise.all([a.open, b.open]);
await a.wait('welcome');
await b.wait('welcome');
ok(a.id && b.id && a.id !== b.id, 'both clients got distinct ids');

// lobby create / join
a.send({ t: 'create', name: 'ALICE' });
const lob1 = await a.wait('lobby');
ok(/^[A-Z]{4}$/.test(lob1.code), `lobby code issued (${lob1.code})`);
ok(lob1.host === a.id, 'creator is host');

b.send({ t: 'join', code: lob1.code.toLowerCase(), name: 'BOB' });
const lob2a = await a.wait('lobby');
const lob2b = await b.wait('lobby');
ok(lob2a.players.length === 2 && lob2b.players.length === 2, 'both see 2 players after join');

// bad code rejected
const c = client('C');
await c.open; await c.wait('welcome');
c.send({ t: 'join', code: 'ZZZZ', name: 'EVE' });
const err = await c.wait('err');
ok(err.m === 'LOBBY NOT FOUND', 'bad code rejected');
c.ws.close();

// non-host cannot set mode or start
b.send({ t: 'mode', mode: 'dm' });
b.send({ t: 'start' });
await new Promise(r => setTimeout(r, 150));
ok(!b.inbox.some(m => m.t === 'start'), 'non-host cannot start');

// host sets DM and starts
a.send({ t: 'mode', mode: 'dm' });
await a.wait('lobby'); await b.wait('lobby');
a.send({ t: 'start' });
const startA = await a.wait('start');
const startB = await b.wait('start');
ok(startA.mode === 'dm' && startB.botCount === 0, 'match started in DM, no bots');
ok(startA.players.every(p => p.spawn !== undefined), 'spawns assigned');

// state relay
a.send({ t: 'state', p: [1, 2], yaw: 0.5, c: 0, m: 1 });
const st = await b.wait('state');
ok(st.from === a.id && st.p[0] === 1, 'state relayed with sender id');
ok(!a.inbox.some(m => m.t === 'state'), 'state not echoed to sender');

// shoot relay + targeted hit routing
a.send({ t: 'shoot', f: [0, 1, 0], e: [5, 1, 5] });
await b.wait('shoot');
ok(true, 'shoot relayed');
a.send({ t: 'hit', target: b.id, dmg: 34, head: 0 });
const hit = await b.wait('hit');
ok(hit.from === a.id && hit.dmg === 34, 'hit routed to victim only');

// kill scoring: B dies to A nine times, A should win at kill 10
for (let i = 0; i < 9; i++) {
  b.send({ t: 'died', killer: a.id });
  const d = await a.wait('died');
  if (i === 0) ok(d.scores.find(s => s.id === a.id).k === 1, 'scores update on death');
  await b.wait('died');
}
b.send({ t: 'died', killer: a.id });
const endA = await a.wait('end');
ok(endA.reason === 'winner' && endA.winner === a.id, 'first to 10 kills wins');
ok(endA.scores.find(s => s.id === a.id).k === 10, 'winner has 10 kills');

// after end, lobby is reusable: start co-op
a.send({ t: 'mode', mode: 'coop' });
await a.wait('lobby');
a.send({ t: 'start' });
const start2 = await b.wait('start');
ok(start2.mode === 'coop' && start2.botCount === 8, 'rematch in co-op with 8 bots');

// hitBot routes to host only
b.send({ t: 'hitBot', id: 3, dmg: 34, sp: [0, 0] });
const hb = await a.wait('hitBot');
ok(hb.id === 3 && hb.from === b.id, 'hitBot routed to host');

// host reports co-op clear
a.send({ t: 'end', reason: 'clear' });
const end2 = await b.wait('end');
ok(end2.reason === 'clear', 'co-op clear broadcast');

// host leaves mid-match → remaining player becomes host
a.send({ t: 'start' });
await b.wait('start');
a.ws.close();
const lob3 = await b.wait('lobby');
const end3 = await b.wait('end');
ok(lob3.host === b.id, 'host migrated to remaining player');
ok(end3.reason === 'hostleft', 'match ended when host left');

b.ws.close();
console.log(failed === 0 ? '\nALL TESTS PASSED' : `\n${failed} TESTS FAILED`);
process.exit(failed === 0 ? 0 : 1);
